using System.Collections.Generic;
using UnityEngine;

namespace TC2.Game
{
    /// <summary>
    /// (session 31: the interface as one hand) The HUD's art, generated by `tc2/art/ui_kit.py` into Resources/UI: night-blue vellum panels with gold rules,
    /// enamel seals with icons, the book's type everywhere (IM FELL English for titles and names, EB Garamond for words and figures - the book, the bars and the
    /// map are one hand), thin scrollbars, gold lozenge sliders. Nothing here reads the world. Also the small kit every part of the HUD draws with: an icon, a
    /// seal that is a button, a word with a tip, a lit ring for the guide.
    /// </summary>
    public sealed partial class Hud
    {
        readonly Dictionary<string, Texture2D> _uiTex = new Dictionary<string, Texture2D>();
        GUIStyle _dateBig, _dateSub, _speedWord, _tipName, _capLabel, _leatherBox, _haloBox, _panelSoft, _pageWord, _hudWord;
        bool _skinDone;

        /// <summary>An interface image from Resources/UI, kept once loaded (a plain white pixel if it is missing, so a mistake shows and breaks nothing).</summary>
        Texture2D Ui(string name)
        {
            if (_uiTex.TryGetValue(name, out var t) && t != null) return t;
            t = Resources.Load<Texture2D>("UI/" + name);
            if (t == null) t = Texture2D.whiteTexture;
            _uiTex[name] = t;
            return t;
        }

        /// <summary>The skin: fonts and backgrounds over the styles Styles() makes, and IMGUI's own scrollbars and sliders. Once.</summary>
        void SkinStyles()
        {
            if (_skinDone) return;
            _skinDone = true;
            _serif = Resources.Load<Font>("Fonts/EBGaramond");
            _display = Resources.Load<Font>("Fonts/IMFellEnglish");
            if (_display == null) _display = _serif;
            var cream = new Color(0.93f, 0.90f, 0.82f);
            var dim = new Color(0.76f, 0.73f, 0.66f);
            var gold = new Color(0.97f, 0.86f, 0.60f);

            _box.normal.background = Ui("panel");
            _box.border = new RectOffset(18, 18, 18, 18);
            _box.padding = new RectOffset(14, 14, 10, 10);
            _panelSoft = new GUIStyle(_box);
            _panelSoft.normal.background = Ui("tag");
            _panelSoft.border = new RectOffset(7, 7, 7, 7);

            _label.font = _serif; _label.fontSize = 16; _label.normal.textColor = cream;
            _small.font = _serif; _small.fontSize = 14; _small.normal.textColor = dim;
            _title.font = _serif; _title.fontSize = 20; _title.normal.textColor = gold;

            foreach (var st in new[] { _btn })
            {
                st.font = _serif; st.fontSize = 15;
                st.normal.background = Ui("btn"); st.focused.background = Ui("btn");
                st.hover.background = Ui("btn_hover"); st.active.background = Ui("btn_on");
                st.onNormal.background = Ui("btn_on"); st.onFocused.background = Ui("btn_on"); st.onHover.background = Ui("btn_on"); st.onActive.background = Ui("btn_on");
                st.border = new RectOffset(8, 8, 8, 8);
                st.padding = new RectOffset(11, 11, 4, 5);
                st.normal.textColor = cream; st.focused.textColor = cream;
                st.hover.textColor = new Color(1f, 0.90f, 0.62f);
                st.active.textColor = Color.white;
                st.onNormal.textColor = new Color(1f, 0.93f, 0.72f); st.onFocused.textColor = new Color(1f, 0.93f, 0.72f); st.onHover.textColor = Color.white;
            }
            _lineStyle.font = _serif; _lineStyle.fontSize = 15;
            _lineSel.font = _serif; _lineSel.fontSize = 15;

            // names on the map, as on an old map: the towns in the book's display type, their lines in its italic; a dark edge over any ground
            _mapName.font = _display; _mapName.fontStyle = FontStyle.Normal; _mapName.fontSize = 15; _mapName.normal.textColor = new Color(1f, 0.97f, 0.88f);
            _mapTown.font = _display; _mapTown.fontStyle = FontStyle.Normal; _mapTown.fontSize = 19; _mapTown.normal.textColor = new Color(1f, 0.94f, 0.76f);
            _mapSub.font = _serif; _mapSub.fontStyle = FontStyle.Italic; _mapSub.fontSize = 13; _mapSub.normal.textColor = new Color(0.94f, 0.91f, 0.82f);

            // the tag under the pointer, and every tip: a small panel of the same vellum
            _mapTag.font = _serif; _mapTag.fontSize = 14; _mapTag.normal.background = Ui("tag"); _mapTag.border = new RectOffset(7, 7, 7, 7);
            _mapTag.padding = new RectOffset(10, 10, 6, 7); _mapTag.normal.textColor = new Color(0.96f, 0.94f, 0.88f);

            GUIStyle L(Font f, int size, Color c, FontStyle fs = FontStyle.Normal, TextAnchor a = TextAnchor.MiddleLeft)
            {
                var st = new GUIStyle(GUI.skin.label) { font = f, fontSize = size, fontStyle = fs, alignment = a, wordWrap = false, richText = true, padding = new RectOffset(0, 0, 0, 0), margin = new RectOffset(0, 0, 0, 0), clipping = TextClipping.Overflow };
                st.normal.textColor = c;
                return st;
            }
            _dateBig = L(_serif, 22, gold, FontStyle.Bold);
            _dateSub = L(_serif, 14, cream);
            _speedWord = L(_serif, 14, cream, FontStyle.Italic);
            _capLabel = L(_display, 12, new Color(0.87f, 0.75f, 0.50f), a: TextAnchor.MiddleCenter);
            _tipName = L(_display, 17, gold);
            _hudWord = L(_serif, 15, cream);
            _pageWord = L(_serif, 15, cream);

            _leatherBox = new GUIStyle { border = new RectOffset(24, 24, 24, 24) };
            _leatherBox.normal.background = Ui("leather");
            _haloBox = new GUIStyle { border = new RectOffset(30, 30, 30, 30) };
            _haloBox.normal.background = Ui("halo");

            // IMGUI's own parts: thin scrollbars with no arrows, a gold lozenge on a dark track
            var sk = GUI.skin;
            sk.verticalScrollbar.normal.background = Ui("sbar_track");
            sk.verticalScrollbar.border = new RectOffset(3, 3, 3, 3);
            sk.verticalScrollbar.fixedWidth = 7f;
            sk.verticalScrollbar.margin = new RectOffset(4, 0, 0, 0);
            sk.verticalScrollbar.padding = new RectOffset(0, 0, 0, 0);
            sk.verticalScrollbarThumb.normal.background = Ui("sbar_thumb");
            sk.verticalScrollbarThumb.hover.background = Ui("sbar_thumb");
            sk.verticalScrollbarThumb.active.background = Ui("sbar_thumb");
            sk.verticalScrollbarThumb.border = new RectOffset(3, 3, 3, 3);
            sk.verticalScrollbarThumb.fixedWidth = 7f;
            foreach (var b in new[] { sk.verticalScrollbarUpButton, sk.verticalScrollbarDownButton })
            {
                b.fixedHeight = 0f; b.fixedWidth = 0f; b.normal.background = null; b.hover.background = null; b.active.background = null; b.margin = new RectOffset(0, 0, 0, 0); b.padding = new RectOffset(0, 0, 0, 0); b.border = new RectOffset(0, 0, 0, 0); b.stretchHeight = false; b.stretchWidth = false;
            }
            sk.horizontalSlider.normal.background = Ui("track");
            sk.horizontalSlider.border = new RectOffset(4, 4, 4, 4);
            sk.horizontalSlider.fixedHeight = 8f;
            sk.horizontalSlider.margin = new RectOffset(6, 6, 8, 8);
            sk.horizontalSlider.padding = new RectOffset(0, 0, 0, 0);
            sk.horizontalSliderThumb.normal.background = Ui("thumb");
            sk.horizontalSliderThumb.hover.background = Ui("thumb_hover");
            sk.horizontalSliderThumb.active.background = Ui("thumb_hover");
            sk.horizontalSliderThumb.fixedWidth = 20f; sk.horizontalSliderThumb.fixedHeight = 20f;
            sk.horizontalSliderThumb.margin = new RectOffset(0, 0, -6, 0);
            sk.horizontalSliderThumb.overflow = new RectOffset(0, 0, 0, 0);
            sk.textField.font = _serif; sk.textField.fontSize = 17;
            sk.textField.normal.background = Ui("btn"); sk.textField.hover.background = Ui("btn_hover"); sk.textField.focused.background = Ui("btn_hover");
            sk.textField.border = new RectOffset(8, 8, 8, 8); sk.textField.padding = new RectOffset(10, 10, 5, 6);
            sk.textField.normal.textColor = cream; sk.textField.hover.textColor = cream; sk.textField.focused.textColor = Color.white;
            sk.settings.cursorColor = gold; sk.settings.selectionColor = new Color(0.8f, 0.6f, 0.2f, 0.4f);
        }

        /// <summary>An icon tinted (white on clear in its image), kept square in a box.</summary>
        void Icon(Rect r, string name, Color c)
        {
            if (Event.current.type != EventType.Repaint) return;
            var old = GUI.color;
            GUI.color = new Color(c.r, c.g, c.b, c.a * old.a);
            GUI.DrawTexture(r, Ui("i_" + name), ScaleMode.ScaleToFit, true);
            GUI.color = old;
        }

        static Rect Inset(Rect r, float by) => new Rect(r.x + by, r.y + by, r.width - by * 2f, r.height - by * 2f);

        /// <summary>A round seal with an icon, as a button: true when clicked. <paramref name="spent"/> dims it; <paramref name="on"/> lights it; a tip is asked for under the pointer.</summary>
        bool Seal(Rect r, string icon, bool on, bool spent, Color tint, out bool hover, float iconShare = 0.54f)
        {
            var e = Event.current;
            hover = r.Contains(e.mousePosition);
            if (e.type == EventType.Repaint)
            {
                var tex = Ui(on ? "seal_on" : spent ? "seal_spent" : hover ? "seal_hover" : "seal");
                if (on || hover)
                {
                    var old = GUI.color;
                    float pulse = on ? 0.45f + 0.25f * Mathf.Sin(Time.unscaledTime * 4f) : 0.30f;
                    GUI.color = new Color(1f, 0.82f, 0.45f, pulse * old.a);
                    GUI.DrawTexture(Inset(r, -r.width * 0.28f), Ui("glow"));
                    GUI.color = old;
                }
                GUI.DrawTexture(r, tex);
                float ins = r.width * (1f - iconShare) * 0.5f;
                Icon(Inset(r, ins), icon, spent ? new Color(tint.r, tint.g, tint.b, 0.42f) : on ? new Color(1f, 0.97f, 0.88f) : tint);
            }
            bool click = GUI.Button(r, GUIContent.none, GUIStyle.none);
            if (click) AudioView.Ui("click");
            return click;
        }

        /// <summary>A tip asked for this frame, above or below a rect: drawn over everything at the frame's end. Its first line in the book's title type if given.</summary>
        void TipAt(Rect over, string text, bool above)
        {
            if (Event.current.type != EventType.Repaint) return;
            if (_tipStyle == null) _tipStyle = new GUIStyle(_mapTag) { wordWrap = true };
            var c = new GUIContent(text);
            float tw = Mathf.Min(420f, _tipStyle.CalcSize(c).x + 2f), th = _tipStyle.CalcHeight(c, tw);
            float sw = Screen.width / _scale, sh = Screen.height / _scale;
            float x = Mathf.Clamp(over.center.x - tw * 0.5f, 6f, sw - tw - 6f);
            float y = above ? over.y - th - 6f : over.yMax + 6f;
            if (y < 4f) y = over.yMax + 6f;
            if (y + th > sh - 4f) y = sh - th - 4f;
            _tip = c; _tipRect = new Rect(x, y, tw, th);
        }

        /// <summary>The binding round a book or a leaf: dark leather with a tooled gold rule (a 9-slice).</summary>
        void Binding(Rect r)
        {
            if (Event.current.type == EventType.Repaint) _leatherBox.Draw(r, false, false, false, false);
        }

        /// <summary>A gold ring round something on the screen, breathing (the guide's mark).</summary>
        void Halo(Rect r)
        {
            if (Event.current.type != EventType.Repaint || r.width <= 0f) return;
            var old = GUI.color;
            GUI.color = new Color(1f, 1f, 1f, 0.72f + 0.28f * Mathf.Sin(Time.unscaledTime * 3.2f));
            _haloBox.Draw(new Rect(r.x - 28f, r.y - 28f, r.width + 56f, r.height + 56f), false, false, false, false);
            GUI.color = old;
        }

        /// <summary>The ornamental rule: a gold line thinning to its ends with a small globe at its heart.</summary>
        void Ornament(Rect r, float alpha = 1f)
        {
            if (Event.current.type != EventType.Repaint) return;
            var old = GUI.color;
            GUI.color = new Color(1f, 1f, 1f, alpha * old.a);
            GUI.DrawTexture(r, Ui("divider"), ScaleMode.StretchToFill, true);
            GUI.color = old;
        }
    }
}
